import { useState, useEffect, useCallback } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
  Legend, ResponsiveContainer, Cell
} from "recharts";

const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000";

async function api(path) {
  const res = await fetch(`${BASE_URL}${path}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function qs(params = {}) {
  const p = Object.fromEntries(
    Object.entries(params).filter(([, v]) => v !== null && v !== undefined && v !== "")
  );
  const s = new URLSearchParams(p).toString();
  return s ? "?" + s : "";
}

// ── Palette — one colour per SKU, consistent across all 3 charts ─────────────
const SKU_COLORS = [
  "#F97316", "#3B82F6", "#10B981", "#8B5CF6",
  "#F59E0B", "#EC4899", "#06B6D4", "#84CC16",
  "#EF4444", "#A78BFA", "#34D399", "#FCD34D",
];

function skuColor(sku, skuList) {
  const i = skuList.indexOf(sku);
  return SKU_COLORS[i % SKU_COLORS.length];
}

// ── Friendly store display name ───────────────────────────────────────────────
// Uses whatever store_name the parser extracted from the file — no hardcoding.
// Falls back to store_code if store_name is missing.
function friendlyStore(store) {
  return (store.store_name || store.store_code || "Unknown Store").trim();
}

// ── Stacked bar chart component ───────────────────────────────────────────────
function StackedChart({ title, subtitle, data, valueKey, formatter, skuList, isLoading }) {
  if (isLoading) {
    return (
      <div style={styles.chartCard}>
        <div style={styles.chartTitle}>{title}</div>
        <div style={styles.shimmer} />
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div style={styles.chartCard}>
        <div style={styles.chartTitle}>{title}</div>
        <div style={styles.empty}>No data for selected filters</div>
      </div>
    );
  }

  // Pivot: [{month_year, SKU1: val, SKU2: val, ...}]
  const pivotMap = {};
  const MONTH_ORDER = ["January","February","March","April","May","June",
    "July","August","September","October","November","December"];

  data.forEach(r => {
    const key = `${r.month} ${r.year}`;
    if (!pivotMap[key]) {
      pivotMap[key] = {
        month_year: key,
        _sort: r.year * 100 + (MONTH_ORDER.indexOf(r.month) + 1),
      };
    }
    pivotMap[key][r.sku_name] = (pivotMap[key][r.sku_name] || 0) + (r[valueKey] || 0);
  });

  const chartData = Object.values(pivotMap).sort((a, b) => a._sort - b._sort);

  return (
    <div style={styles.chartCard}>
      <div style={styles.chartTitle}>{title}</div>
      {subtitle && <div style={styles.chartSubtitle}>{subtitle}</div>}
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={chartData} margin={{ top: 8, right: 16, left: 8, bottom: 40 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)" />
          <XAxis
            dataKey="month_year"
            tick={{ fill: "#94a3b8", fontSize: 11 }}
            angle={-35}
            textAnchor="end"
            interval={0}
          />
          <YAxis
            tick={{ fill: "#94a3b8", fontSize: 11 }}
            tickFormatter={formatter}
          />
          <Tooltip
            contentStyle={{ background: "#1e293b", border: "1px solid #334155", borderRadius: 8 }}
            labelStyle={{ color: "#f1f5f9", fontWeight: 600 }}
            itemStyle={{ color: "#cbd5e1" }}
            formatter={(val, name) => [formatter(val), name.replace("SVASTHYAA ", "")]}
          />
          <Legend
            wrapperStyle={{ fontSize: 11, color: "#94a3b8", paddingTop: 16 }}
            formatter={(val) => val.replace("SVASTHYAA ", "")}
          />
          {skuList.map((sku) => (
            <Bar key={sku} dataKey={sku} stackId="a" fill={skuColor(sku, skuList)} radius={0} />
          ))}
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

// ── SOH Chart (grouped by store, stacked by SKU) ──────────────────────────────
function SohChart({ data, skuList, isLoading }) {
  if (isLoading) {
    return (
      <div style={styles.chartCard}>
        <div style={styles.chartTitle}>Stock on Hand</div>
        <div style={styles.shimmer} />
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div style={styles.chartCard}>
        <div style={styles.chartTitle}>Stock on Hand</div>
        <div style={styles.empty}>No SOH data available</div>
      </div>
    );
  }

  // Pivot by store_name
  const pivotMap = {};
  data.forEach(r => {
    const key = friendlyStore(r);
    if (!pivotMap[key]) pivotMap[key] = { store: key };
    pivotMap[key][r.sku_name] = (pivotMap[key][r.sku_name] || 0) + (r.soh_qty || 0);
  });

  const chartData = Object.values(pivotMap);

  return (
    <div style={styles.chartCard}>
      <div style={styles.chartTitle}>Stock on Hand</div>
      <div style={styles.chartSubtitle}>Current units in store — latest upload</div>
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={chartData} margin={{ top: 8, right: 16, left: 8, bottom: 40 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)" />
          <XAxis dataKey="store" tick={{ fill: "#94a3b8", fontSize: 11 }} />
          <YAxis tick={{ fill: "#94a3b8", fontSize: 11 }} />
          <Tooltip
            contentStyle={{ background: "#1e293b", border: "1px solid #334155", borderRadius: 8 }}
            labelStyle={{ color: "#f1f5f9", fontWeight: 600 }}
            itemStyle={{ color: "#cbd5e1" }}
            formatter={(val, name) => [`${val} units`, name.replace("SVASTHYAA ", "")]}
          />
          <Legend
            wrapperStyle={{ fontSize: 11, color: "#94a3b8", paddingTop: 16 }}
            formatter={(val) => val.replace("SVASTHYAA ", "")}
          />
          {skuList.map((sku) => (
            <Bar key={sku} dataKey={sku} stackId="a" fill={skuColor(sku, skuList)} radius={0} />
          ))}
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

// ── Summary KPI strip ─────────────────────────────────────────────────────────
function KpiStrip({ revenueData, qtyData, sohData }) {
  const totalRev = revenueData.reduce((s, r) => s + (r.total_revenue || 0), 0);
  const totalQty = qtyData.reduce((s, r) => s + (r.total_qty || 0), 0);
  const totalSoh = sohData.reduce((s, r) => s + (r.soh_qty || 0), 0);

  const kpis = [
    { label: "Total Revenue", value: `₹${(totalRev / 1000).toFixed(1)}K`, icon: "ti-currency-rupee" },
    { label: "Units Sold", value: totalQty.toLocaleString(), icon: "ti-package" },
    { label: "Units in Stock", value: totalSoh.toLocaleString(), icon: "ti-stack" },
  ];

  return (
    <div style={styles.kpiStrip}>
      {kpis.map(k => (
        <div key={k.label} style={styles.kpiCard}>
          <i className={`ti ${k.icon}`} style={styles.kpiIcon} />
          <div style={styles.kpiValue}>{k.value}</div>
          <div style={styles.kpiLabel}>{k.label}</div>
        </div>
      ))}
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────
export default function ModernTradeAnalytics() {
  const [chains, setChains]         = useState([]);
  const [stores, setStores]         = useState([]);
  const [months, setMonths]         = useState([]);
  const [skus, setSkus]             = useState([]);

  // Selected filters
  const [selChain, setSelChain]     = useState("");
  const [selStore, setSelStore]     = useState("");
  const [selMonth, setSelMonth]     = useState("");
  const [selYear, setSelYear]       = useState("");
  const [selSku, setSelSku]         = useState("");

  // Data
  const [revenueData, setRevenueData] = useState([]);
  const [qtyData, setQtyData]         = useState([]);
  const [sohData, setSohData]         = useState([]);

  // Loading
  const [loadingChains, setLoadingChains] = useState(true);
  const [loadingCharts, setLoadingCharts] = useState(false);

  // All unique SKUs across visible data (for consistent colour mapping)
  const allSkus = [...new Set([
    ...revenueData.map(r => r.sku_name),
    ...qtyData.map(r => r.sku_name),
    ...sohData.map(r => r.sku_name),
  ])].sort();

  // Load chains on mount
  useEffect(() => {
    api("/mt/chains")
      .then(setChains)
      .catch(console.error)
      .finally(() => setLoadingChains(false));
  }, []);

  // Load stores + months + SKUs when chain changes
  useEffect(() => {
    if (!selChain) {
      setStores([]); setMonths([]); setSkus([]);
      setSelStore(""); setSelMonth(""); setSelYear(""); setSelSku("");
      return;
    }
    Promise.all([
      api(`/mt/analytics/stores${qs({ chain: selChain })}`),
      api(`/mt/analytics/months${qs({ chain: selChain })}`),
      api(`/mt/analytics/skus${qs({ chain: selChain })}`),
    ]).then(([s, m, k]) => {
      setStores(s);
      setMonths(m);
      setSkus(k);
      setSelStore(""); setSelMonth(""); setSelYear(""); setSelSku("");
    }).catch(console.error);
  }, [selChain]);

  // Load chart data when any filter changes
  const loadCharts = useCallback(() => {
    const params = {
      chain:      selChain  || undefined,
      store_code: selStore  || undefined,
      month:      selMonth  || undefined,
      year:       selYear   || undefined,
      sku:        selSku    || undefined,
    };
    setLoadingCharts(true);
    Promise.all([
      api(`/mt/analytics/revenue-by-sku${qs(params)}`),
      api(`/mt/analytics/revenue-by-sku${qs(params)}`), // same data, qty field
      api(`/mt/analytics/soh${qs({ chain: params.chain, store_code: params.store_code, sku: params.sku })}`),
    ]).then(([rev, qty, soh]) => {
      setRevenueData(rev);
      setQtyData(qty);
      setSohData(soh);
    }).catch(console.error)
      .finally(() => setLoadingCharts(false));
  }, [selChain, selStore, selMonth, selYear, selSku]);

  useEffect(() => { loadCharts(); }, [loadCharts]);

  // Unique years from months
  const years = [...new Set(months.map(m => m.year))].sort();
  // Filtered month list by selected year
  const monthsFiltered = selYear
    ? months.filter(m => String(m.year) === String(selYear))
    : months;

  // Stores scoped to selected chain
  const visibleStores = selChain
    ? stores.filter(s => s.chain_name === selChain)
    : stores;

  if (loadingChains) {
    return (
      <div style={styles.page}>
        <div style={styles.loadingMsg}>Loading Modern Trade data…</div>
      </div>
    );
  }

  return (
    <div style={styles.page}>

      {/* ── Header ── */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Modern Trade Analytics</h1>
          <p style={styles.subtitle}>
            {selChain
              ? `${selChain} — ${visibleStores.length} store${visibleStores.length !== 1 ? "s" : ""}`
              : "Select a chain to drill down by store"}
          </p>
        </div>
      </div>

      {/* ── Filter bar ── */}
      <div style={styles.filterBar}>

        {/* Chain */}
        <div style={styles.filterGroup}>
          <label style={styles.filterLabel}>MT Chain</label>
          <select
            style={styles.select}
            value={selChain}
            onChange={e => setSelChain(e.target.value)}
          >
            <option value="">All Chains</option>
            {chains.map(c => (
              <option key={c.id} value={c.chain_name}>{c.chain_name}</option>
            ))}
          </select>
        </div>

        {/* Store — auto-populated when chain is selected */}
        <div style={styles.filterGroup}>
          <label style={styles.filterLabel}>Store</label>
          <select
            style={styles.select}
            value={selStore}
            onChange={e => setSelStore(e.target.value)}
            disabled={!selChain}
          >
            <option value="">All Stores</option>
            {visibleStores.map(s => (
              <option key={s.store_code} value={s.store_code}>
                {friendlyStore(s)}
              </option>
            ))}
          </select>
        </div>

        {/* Year */}
        <div style={styles.filterGroup}>
          <label style={styles.filterLabel}>Year</label>
          <select
            style={styles.select}
            value={selYear}
            onChange={e => { setSelYear(e.target.value); setSelMonth(""); }}
            disabled={!selChain}
          >
            <option value="">All Years</option>
            {years.map(y => (
              <option key={y} value={y}>{y}</option>
            ))}
          </select>
        </div>

        {/* Month */}
        <div style={styles.filterGroup}>
          <label style={styles.filterLabel}>Month</label>
          <select
            style={styles.select}
            value={selMonth}
            onChange={e => setSelMonth(e.target.value)}
            disabled={!selChain}
          >
            <option value="">All Months</option>
            {monthsFiltered.map(m => (
              <option key={`${m.month}-${m.year}`} value={m.month}>{m.month} {m.year}</option>
            ))}
          </select>
        </div>

        {/* SKU */}
        <div style={styles.filterGroup}>
          <label style={styles.filterLabel}>SKU</label>
          <select
            style={styles.select}
            value={selSku}
            onChange={e => setSelSku(e.target.value)}
            disabled={!selChain}
          >
            <option value="">All SKUs</option>
            {skus.map(s => (
              <option key={s.sku_name} value={s.sku_name}>
                {s.sku_name.replace("SVASTHYAA ", "")}
              </option>
            ))}
          </select>
        </div>

        {/* Reset */}
        {(selChain || selStore || selMonth || selYear || selSku) && (
          <button
            style={styles.resetBtn}
            onClick={() => {
              setSelChain(""); setSelStore(""); setSelMonth("");
              setSelYear(""); setSelSku("");
            }}
          >
            <i className="ti ti-x" /> Reset
          </button>
        )}
      </div>

      {/* ── Chain-level summary strip (shown when chain selected, no store) ── */}
      {selChain && !selStore && (
        <div style={styles.storeChips}>
          <span style={styles.chipLabel}>Stores in {selChain}:</span>
          {visibleStores.map(s => (
            <button
              key={s.store_code}
              style={{
                ...styles.chip,
                ...(selStore === s.store_code ? styles.chipActive : {}),
              }}
              onClick={() => setSelStore(selStore === s.store_code ? "" : s.store_code)}
            >
              {friendlyStore(s)}
            </button>
          ))}
        </div>
      )}

      {/* ── KPI strip ── */}
      {!loadingCharts && (revenueData.length > 0 || sohData.length > 0) && (
        <KpiStrip revenueData={revenueData} qtyData={qtyData} sohData={sohData} />
      )}

      {/* ── Charts ── */}
      <div style={styles.chartsGrid}>
        <StackedChart
          title="Revenue by SKU"
          subtitle="₹ stacked by SKU per month"
          data={revenueData}
          valueKey="total_revenue"
          formatter={v => `₹${(v / 1000).toFixed(1)}K`}
          skuList={allSkus}
          isLoading={loadingCharts}
        />

        <StackedChart
          title="Units Sold by SKU"
          subtitle="Qty stacked by SKU per month"
          data={qtyData}
          valueKey="total_qty"
          formatter={v => `${v} units`}
          skuList={allSkus}
          isLoading={loadingCharts}
        />

        <SohChart
          data={sohData}
          skuList={allSkus}
          isLoading={loadingCharts}
        />
      </div>

      {/* ── Empty state ── */}
      {!loadingCharts && chains.length === 0 && (
        <div style={styles.emptyPage}>
          <i className="ti ti-building-store" style={{ fontSize: 48, color: "#334155" }} />
          <p style={{ color: "#64748b", marginTop: 16 }}>
            No Modern Trade data yet. Upload an MT Excel file to get started.
          </p>
        </div>
      )}
    </div>
  );
}

